public void effectuate(CreditApplicationOrder order) {
    BigDecimal limitAmount = order.getApprovedLimit();
    switch (order.getType()) {
        case INITIAL -> {
            CreditLimit limit = new CreditLimit();
            String creditId = Ids.next("CR-");
            limit.setCreditId(creditId);
            limit.setCustomerName(order.getCustomerName());
            limit.setTotalLimit(limitAmount);
            limit.setOccupied(BigDecimal.ZERO);
            limit.setPreOccupied(BigDecimal.ZERO);
            limit.setFrozen(false);
            limit.setRestricted(false);
            limitRepo.save(limit);
            order.setCreatedCreditId(creditId);
            applyLayers(order, creditId);
        }
        case LIMIT_INCREASE, RENEWAL -> {
            CreditLimit limit = requireCredit(order.getTargetCreditId());
            limit.setTotalLimit(limitAmount);
            limit.setRestricted(limit.getOccupied().add(limit.getPreOccupied()).compareTo(limitAmount) > 0);
            applyLayers(order, limit.getCreditId());
        }
        case LIMIT_DECREASE -> {
            CreditLimit limit = requireCredit(order.getTargetCreditId());
            limit.setTotalLimit(limitAmount);
            // 降额规则：占用高于新上限时保留实际占用、限制新增提款，不改已有债务
            limit.setRestricted(limit.getOccupied().add(limit.getPreOccupied()).compareTo(limitAmount) > 0);
        }

