        sub.setOccupied(sub.getOccupied().subtract(principalPortion).max(BigDecimal.ZERO));
        record(creditId, LimitRecord.Layer.PRODUCT, LimitRecord.Kind.RELEASE,
                LimitRecord.Reason.PRINCIPAL_REPAID, principalPortion, productId, bizOrderNo, loanAccountNo);
    });
    findGroupOf(creditId).ifPresent(group -> {
        group.setOccupied(group.getOccupied().subtract(principalPortion).max(BigDecimal.ZERO));
        record(creditId, LimitRecord.Layer.GROUP, LimitRecord.Kind.RELEASE,
                LimitRecord.Reason.PRINCIPAL_REPAID, principalPortion, null, bizOrderNo, loanAccountNo);
    });
    if (productRequiresGuarantee) {
        findCoverage(creditId).ifPresent(coverage -> {
            // 部分还本按规则减少担保覆盖占用（主场景：还本 10 万、覆盖比例 80% → 覆盖占用减 8 万）
            BigDecimal release = principalPortion.multiply(coverage.getCoverageRatio())
                    .setScale(2, java.math.RoundingMode.DOWN);
            coverage.setOccupied(coverage.getOccupied().subtract(release).max(BigDecimal.ZERO));
            record(creditId, LimitRecord.Layer.GUARANTEE, LimitRecord.Kind.RELEASE,
                    LimitRecord.Reason.PRINCIPAL_REPAID, release, null, bizOrderNo, loanAccountNo);

public void effectuate(CreditApplicationOrder order) {
    BigDecimal limitAmount = order.getApprovedLimit();
    switch (order.getType()) {
        case INITIAL -> {
            CreditLimit limit = new CreditLimit();
            String creditId = Ids.next("CR-");
            limit.setCreditId(creditId);
            limit.setCustomerName(order.getCustomerName());
            limit.setTotalLimit(limitAmount);
            limit.setOccupied(BigDecimal.ZERO);
            limit.setPreOccupied(BigDecimal.ZERO);
            limit.setFrozen(false);
            limit.setRestricted(false);
            limitRepo.save(limit);
            order.setCreatedCreditId(creditId);
            applyLayers(order, creditId);
        }
        case LIMIT_INCREASE, RENEWAL -> {
            CreditLimit limit = requireCredit(order.getTargetCreditId());
            limit.setTotalLimit(limitAmount);
            limit.setRestricted(limit.getOccupied().add(limit.getPreOccupied()).compareTo(limitAmount) > 0);
            applyLayers(order, limit.getCreditId());
        }
        case LIMIT_DECREASE -> {
            CreditLimit limit = requireCredit(order.getTargetCreditId());
            limit.setTotalLimit(limitAmount);
            // 降额规则：占用高于新上限时保留实际占用、限制新增提款，不改已有债务
            limit.setRestricted(limit.getOccupied().add(limit.getPreOccupied()).compareTo(limitAmount) > 0);
        }

private ProductConfigVersion resolveVersion(ProductConfig product) {
    Optional<ProductConfigVersion> latest = versionRepo.findFirstByProductIdOrderByVersionDesc(product.getProductId());
    if (latest.isPresent() && sameRules(latest.get(), product)) {
        return latest.get();
    }
    ProductConfigVersion version = new ProductConfigVersion();
    version.setVersionId("PV-" + product.getProductId() + "-"
            + (latest.map(v -> v.getVersion() + 1).orElse(1)));
    version.setProductId(product.getProductId());
    version.setVersion(latest.map(v -> v.getVersion() + 1).orElse(1));
    version.setMinAmount(product.getMinAmount());
    version.setMaxAmount(product.getMaxAmount());
    version.setTerms(product.getTerms());
    version.setRepaymentModes(product.getRepaymentModes());
    version.setAnnualInterestRate(product.getAnnualInterestRate());
    version.setRequiresGuarantee(product.isRequiresGuarantee());
    version.setFineractProductId(product.getFineractProductId());
    version.setEffectiveAt(Ids.now());
    return versionRepo.save(version);
}

private boolean sameRules(ProductConfigVersion version, ProductConfig product) {
    return version.getMinAmount().compareTo(product.getMinAmount()) == 0
            && version.getMaxAmount().compareTo(product.getMaxAmount()) == 0
            && version.getTerms().equals(product.getTerms())
            && version.getRepaymentModes().equals(product.getRepaymentModes())
            && version.getAnnualInterestRate().compareTo(product.getAnnualInterestRate()) == 0
            && version.isRequiresGuarantee() == product.isRequiresGuarantee();

