                LimitRecord.Reason.PRINCIPAL_REPAID, principalPortion, productId, bizOrderNo, loanAccountNo);
    });
    findGroupOf(creditId).ifPresent(group -> {
        group.setOccupied(group.getOccupied().subtract(principalPortion).max(BigDecimal.ZERO));
        record(creditId, LimitRecord.Layer.GROUP, LimitRecord.Kind.RELEASE,
                LimitRecord.Reason.PRINCIPAL_REPAID, principalPortion, null, bizOrderNo, loanAccountNo);

@Scheduled(fixedDelay = 1000)
public void dispatch() {
    List<ExtTransaction> pending = txRepo.findByStatus("PROCESSING");
    for (ExtTransaction tx : pending) {
        if (tx.getProcessDueAt() == null || LocalDateTime.now().withNano(0).isBefore(tx.getProcessDueAt())) {
            continue;
        }
        resolveAndDeliver(tx);
    }
}

@Transactional
void resolveAndDeliver(ExtTransaction tx) {
    if (!tx.isResultResolved()) {
        String status = tx.getScenario() == ExtTransaction.Scenario.ASYNC_FAIL ? "FAILED" : "SUCCESS";
        tx.setStatus(status);
        tx.setResultResolved(true);
        tx.setFinishedAt(LocalDateTime.now().withNano(0));
        if (tx.getKind() == ExtTransaction.Kind.APPROVAL) {
            tx.setResultDetail("SUCCESS".equals(status) ? "APPROVED" : "REJECTED");
            if ("APPROVED".equals(tx.getResultDetail())) {
                tx.setResultAmount(tx.getAmount());
            }
        }
    }
    if (tx.isCallbackSuppressed()) {
        log.info("场景要求不回调，等待中台查单: {}", tx.getExtSerialNo());
        return;
    }
    long attempts = callbackRepo.countByExtSerialNo(tx.getExtSerialNo());
    if (attempts >= props.callbackMaxAttempts()) {
        log.warn("回调重试次数已用尽，等待中台查单: {}", tx.getExtSerialNo());
        return;
    }
    boolean ok = callbackClient.deliver(tx,
            tx.getKind() == ExtTransaction.Kind.APPROVAL ? tx.getResultDetail() : tx.getStatus(),
            tx.getFinishedAt() == null ? "" : tx.getFinishedAt().toString());
    CallbackLog entry = new CallbackLog();
    entry.setLogId("CB-" + tx.getExtSerialNo() + "-" + (attempts + 1));
    entry.setExtSerialNo(tx.getExtSerialNo());
    entry.setAttempt((int) attempts + 1);
    entry.setSuccess(ok);
    entry.setResponse(ok ? "received" : "unreachable");
    entry.setDeliveredAt(LocalDateTime.now().withNano(0));
    callbackRepo.save(entry);

